<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';defineProps({defaultCountryCode:String});const form=useForm({channel:'email',email:'',country_code:'+91',phone:''});</script><template><Head title="Create account"/><main class="flex min-h-screen items-center justify-center bg-ink p-6"><section class="w-full max-w-lg rounded-3xl bg-white p-7 md:p-10"><p class="eyebrow">Join LensPic</p><h1 class="mt-3 font-display text-3xl font-bold">Begin your photography workspace</h1><div class="mt-7 grid grid-cols-2 rounded-xl bg-black/5 p-1"><button v-for="c in ['email','mobile']" :key="c" type="button" :class="['rounded-lg py-2 text-sm font-semibold',form.channel===c?'bg-white shadow-sm':'']" @click="form.channel=c">{{c}}</button></div><form class="mt-6" @submit.prevent="form.post('/send-otp')"><label v-if="form.channel==='email'" class="block text-sm font-semibold">Email address<input v-model="form.email" type="email" class="field mt-2" required></label><div v-else class="grid grid-cols-[100px_1fr] gap-3"><label class="text-sm font-semibold">Code<input v-model="form.country_code" class="field mt-2"></label><label class="text-sm font-semibold">Mobile<input v-model="form.phone" class="field mt-2" required></label></div><button class="btn-primary mt-6 w-full" :disabled="form.processing">Continue securely</button></form><p class="mt-6 text-center text-sm text-black/50">Already registered? <Link href="/login" class="font-semibold text-indigo">Sign in</Link></p></section></main></template>
